namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder",
            Steps = "1. Mix dry ingredients.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients.\n4. Cook on a greased griddle until golden.",
            TotalRatingPoints = 12, RatingCount = 3
        },
        new Recipe
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
            Steps = "1. Toast the bread until golden.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread on toast and sprinkle with red pepper flakes.",
            TotalRatingPoints = 8, RatingCount = 2
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Caesar Salad", Category = "Lunch",
            Ingredients = "2 chicken breasts\n1 head romaine lettuce\nCaesar dressing\nCroutons\nParmesan cheese",
            Steps = "1. Grill chicken breasts and slice.\n2. Chop romaine lettuce.\n3. Toss with dressing, croutons, and parmesan.\n4. Top with sliced chicken.",
            TotalRatingPoints = 14, RatingCount = 3
        },
        new Recipe
        {
            Id = 4, Title = "Grilled Cheese Sandwich", Category = "Lunch",
            Ingredients = "2 slices bread\n2 slices cheddar cheese\n1 tbsp butter",
            Steps = "1. Butter the outside of each bread slice.\n2. Place cheese between bread slices.\n3. Grill in a pan on medium heat until golden on both sides.",
            TotalRatingPoints = 5, RatingCount = 1
        },
        new Recipe
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
            Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion\n3 cloves garlic\nOlive oil\nBasil",
            Steps = "1. Cook spaghetti according to package.\n2. Sauté onion and garlic in olive oil.\n3. Brown the ground beef.\n4. Add crushed tomatoes and simmer 20 minutes.\n5. Serve sauce over spaghetti with fresh basil.",
            TotalRatingPoints = 20, RatingCount = 4
        },
        new Recipe
        {
            Id = 6, Title = "Baked Salmon", Category = "Dinner",
            Ingredients = "4 salmon fillets\n2 tbsp olive oil\n1 lemon\nDill\nSalt and pepper",
            Steps = "1. Preheat oven to 400°F.\n2. Place salmon on a baking sheet.\n3. Drizzle with olive oil, squeeze lemon, season.\n4. Bake 12-15 minutes until flaky.",
            TotalRatingPoints = 9, RatingCount = 2
        },
        new Recipe
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "2.25 cups flour\n1 cup butter\n0.75 cup sugar\n0.75 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
            Steps = "1. Cream butter and sugars.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Bake at 375°F for 9-11 minutes.",
            TotalRatingPoints = 15, RatingCount = 3
        },
        new Recipe
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Ingredients = "6 egg yolks\n0.75 cup sugar\n1.25 cups mascarpone\n2 cups heavy cream\n2 cups espresso\nLadyfinger biscuits\nCocoa powder",
            Steps = "1. Whisk yolks and sugar until thick.\n2. Blend in mascarpone.\n3. Whip cream and fold into mascarpone mixture.\n4. Dip ladyfingers in espresso and layer.\n5. Spread cream mixture and repeat layers.\n6. Dust with cocoa and refrigerate 4 hours.",
            TotalRatingPoints = 10, RatingCount = 2
        }
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

